Put put(Side side, std::uint32_t tick, unsigned mask) noexcept {
        if (side != Side::host && side != Side::peer) {
            return Put::invalid;
        }
        if (!study_input::valid(mask)) {
            return Put::invalid;
        }
        if (exhausted()) {
            return Put::exhausted;
        }

        const std::uint64_t wire = static_cast<std::uint64_t>(tick);
        if (wire < next_) {
            return Put::stale;
        }
        const std::uint64_t offset = wire - next_;
        if (offset >= static_cast<std::uint64_t>(capacity)) {
            return Put::too_far;
        }

        std::array<std::optional<std::uint8_t>, capacity>& slots = slots_for(side);
        const std::size_t index = static_cast<std::size_t>(offset);
        if (slots[index].has_value()) {
            // Preserve what was recorded: only an identical input is harmless.
            return *slots[index] == static_cast<std::uint8_t>(mask) ? Put::duplicate
                                                                   : Put::conflict;
        }
        slots[index] = static_cast<std::uint8_t>(mask);
        return Put::stored;
    }

Put put_batch(Side side, std::uint32_t first, const std::uint8_t* masks,
                  std::size_t count) noexcept {
        if (side != Side::host && side != Side::peer) {
            return Put::invalid;
        }
        if (masks == nullptr) {
            return Put::invalid;
        }
        if (count == 0 || count > capacity) {
            return Put::invalid;
        }
        // The run must not wrap past the end of the uint32 tick space.
        if (static_cast<std::uint64_t>(first) + (count - 1) >
            static_cast<std::uint64_t>(UINT32_MAX)) {
            return Put::invalid;
        }
        for (std::size_t i = 0; i < count; ++i) {
            if (!study_input::valid(masks[i])) {
                return Put::invalid;
            }
        }

        // Commit-or-rollback: build the result on a copy, assign only on success.
        TickInputs candidate = *this;
        bool any_stored = false;
        for (std::size_t i = 0; i < count; ++i) {
            const std::uint32_t tick =
                static_cast<std::uint32_t>(static_cast<std::uint64_t>(first) + i);
            const Put result = candidate.put(side, tick, masks[i]);
            if (result == Put::stored) {
                any_stored = true;
            } else if (result != Put::duplicate) {
                return result; // Whole batch rejected; *this is unchanged.
            }
        }
        *this = candidate;
        return any_stored ? Put::stored : Put::duplicate;
    }

bool peek(std::uint8_t& host, std::uint8_t& peer) const noexcept {
        if (!host_[0].has_value() || !peer_[0].has_value()) {
            return false;
        }
        host = *host_[0];
        peer = *peer_[0];
        return true;
    }

bool consume() noexcept {
        if (!host_[0].has_value() || !peer_[0].has_value()) {
            return false;
        }
        for (std::size_t i = 0; i + 1 < capacity; ++i) {
            host_[i] = host_[i + 1];
            peer_[i] = peer_[i + 1];
        }
        host_[capacity - 1].reset();
        peer_[capacity - 1].reset();
        ++next_;
        return true;
    }

std::uint8_t scripted(study_net::Side side, std::uint32_t tick) {
    if (tick % 3 == 2) return 0;
    if (side == study_net::Side::host)
        return tick % 3 == 0 ? study_input::left : study_input::rotate;
    return tick % 3 == 0 ? study_input::right : study_input::down;
}

Advance advance() noexcept {
        // A consumed tick space can never advance further.
        if (inputs_.exhausted()) {
            return Advance::exhausted;
        }

        // A finished board ends the match; do not consume the pending pair.
        if (duel_.left().finished() || duel_.right().finished()) {
            return Advance::finished;
        }

        // Both input records for this tick must exist; peek leaves them in place.
        std::uint8_t host_mask = 0;
        std::uint8_t peer_mask = 0;
        if (!inputs_.peek(host_mask, peer_mask)) {
            return Advance::waiting;
        }

        // Canonical mapping, independent of which process is running locally.
        const std::optional<study_input::Intent> left = study_input::decode(host_mask);
        const std::optional<study_input::Intent> right = study_input::decode(peer_mask);
        if (!left.has_value() || !right.has_value()) {
            return Advance::invalid;
        }

        // Apply to a copy first: a rejected step leaves duel_ and inputs_ intact.
        study_combat::Duel candidate = duel_;
        if (!candidate.tick(*left, *right).has_value()) {
            return Advance::invalid;
        }

        // Commit the duel, then retire the pair. peek and consume share this
        // single owner, so no interleaving can occur between the two calls.
        duel_ = candidate;
        // peek guaranteed both slot-0 inputs, so consume cannot fail here.
        (void)inputs_.consume();
        // An accepted pair advances next_tick() exactly once, even when the
        // step itself makes a board finished.
        return Advance::advanced;
    }

bool exchange(study_net::Connection& connection, study_net::Lockstep& game,
              study_net::Side local) {
    using namespace study_net;
    for (std::uint32_t tick = 0; tick < kTicks; ++tick)
        if (game.submit(local, tick, scripted(local, tick)) != Put::stored) return false;
    for (const std::uint32_t first : {6u, 0u}) {
        InputBatch batch;
        batch.first_tick = first;
        batch.count = 6;
        for (std::size_t i = 0; i < batch.count; ++i)
            batch.masks[i] = scripted(local, first + static_cast<std::uint32_t>(i));
        Frame frame;
        if (!encode_input_payload(batch, frame)) return false;
        frame.type = kInputType;
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(2);
        if (connection.send_frame(frame, deadline).outcome != SendOutcome::complete) return false;
    }
    int error = 0;
    if (!connection.finish_sending(error)) return false;
    const Side remote = local == Side::host ? Side::peer : Side::host;
    for (;;) {
        Frame frame;
        const auto received = connection.next_frame(frame);
        if (received.state == Connection::ReadState::eof) return game.next_tick() == kTicks;
        if (received.state != Connection::ReadState::frame || frame.type != kInputType) return false;
        InputBatch batch;
        if (!decode_input_payload(frame, batch)) return false;
        // This experiment has exactly twelve ticks. The generic window can hold 32.
        if (batch.first_tick >= kTicks || batch.count > kTicks - batch.first_tick) return false;
        if (!accepted(game.submit_batch(remote, batch.first_tick, batch.masks.data(), batch.count))) return false;
        for (;;) {
            const auto result = game.advance();
            if (result == Advance::advanced) continue;
            if (result != Advance::waiting) return false;
            std::printf("WAIT next=%llu\n",static_cast<unsigned long long>(game.next_tick()));
            break;
        }
    }
}
